// Base class
class Bird {
    method fly() {
        // Generic flying behavior
    }
}

// Subclass that cannot fly
class Ostrich extends Bird {
    method fly() {
        throw Error("Ostrich cannot fly")
    }
}

// Code that expects any Bird to fly
method letBirdFly(bird: Bird) {
    bird.fly()
}

